-- ============================================================================
-- DO NOT EDIT THIS FILE ONCE IT HAS BEEN APPLIED TO ANY DATABASE.
-- Until then it may still change. After it is applied, every change goes in a
-- new migration file with a later timestamp.
-- ============================================================================
--
-- Each schedule keeps the customer's own Indonesian time zone, so its day and
-- hours follow the customer's city (WIB, WITA or WIT) instead of always Bali.
--
-- Add-only: one new nullable column on lead_schedules with a default and a
-- check constraint. No existing column, row, policy or function is changed.
-- starts_at / ends_at stay in UTC; this column only says in which zone the
-- day and times were given and are shown to the customer.
--
-- The default keeps every existing code path and every existing row in Bali
-- time (WITA), which is what they were made in. No backfill (the table had no
-- rows when this was written; any row added before it is applied gets the
-- default, which is correct for it).
--
-- Depends on 20261114090000_lead_schedules.sql.
-- NOT applied to production by the developer. The project owner reviews and
-- applies it with `supabase db push` (see docs/schedules.md).

alter table public.lead_schedules
    add column time_zone text default 'Asia/Makassar';

alter table public.lead_schedules
    add constraint lead_schedules_time_zone_check
        check (time_zone is null or time_zone = any (array['Asia/Jakarta', 'Asia/Makassar', 'Asia/Jayapura']));

comment on column public.lead_schedules.time_zone is 'IANA zone the day and times were given in, from the customer''s location: Asia/Jakarta (WIB, UTC+7), Asia/Makassar (WITA, UTC+8, FSI office) or Asia/Jayapura (WIT, UTC+9). Null reads as Asia/Makassar. starts_at and ends_at stay in UTC.';
